BEGIN;
CREATE SCHEMA IF NOT EXISTS f2_import;
REVOKE ALL ON SCHEMA f2_import FROM PUBLIC,anon,authenticated;
CREATE TABLE IF NOT EXISTS f2_import.fuente_reciente (
 anio smallint NOT NULL,tipo text NOT NULL,clave text NOT NULL,datos jsonb NOT NULL,fuente text NOT NULL,
 PRIMARY KEY(anio,tipo,clave)
);
ALTER TABLE f2_import.fuente_reciente ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE f2_import.fuente_reciente FROM PUBLIC,anon,authenticated;
ON CONFLICT(anio,tipo,clave) DO UPDATE SET datos=excluded.datos,fuente=excluded.fuente;
ON CONFLICT(anio,tipo,clave) DO UPDATE SET datos=excluded.datos,fuente=excluded.fuente;
ON CONFLICT(anio,tipo,clave) DO UPDATE SET datos=excluded.datos,fuente=excluded.fuente;
ON CONFLICT(anio,tipo,clave) DO UPDATE SET datos=excluded.datos,fuente=excluded.fuente;
COMMIT;
SELECT tipo,count(*) AS filas FROM f2_import.fuente_reciente WHERE anio=2025 GROUP BY tipo ORDER BY tipo;
